import fs from 'node:fs';import {execFileSync} from 'node:child_process';
const dir='docs/assets/r2-public/audit-20261009',review=JSON.parse(fs.readFileSync(dir+'/OBJECT-REVIEW.json')),live=JSON.parse(fs.readFileSync(dir+'/ONLINE-LOADS.json')),inventory=JSON.parse(fs.readFileSync(dir+'/INVENTORY.json')),old=JSON.parse(fs.readFileSync('docs/assets/r2-public/r2-bucket-inventory-2026-09-19.json'));
const byKey=new Map(review.rows.map(r=>[r.key,r]));
for(const row of review.rows)if(row.classification==='错绑或仍调用旧版本'){row.classification='已使用';row.reason='当前源码消费者存在；多用途登记和目录 prefix 不单独证明错绑。';}
for(const r of live.receipts){const row=byKey.get(r.key);if(row)row.runtimeObserved.push(r);}
for(const row of review.rows){const loaded=row.runtimeObserved.filter(r=>r.status===200);if(loaded.length){row.classification='已使用';row.reason+=' 本轮公开线上页面实际返回该对象；是否可见解码需见 ONLINE-LOADS.pages。';row.availableSha256=[...new Set(loaded.map(r=>r.sha256).filter(Boolean))];}else row.availableSha256=[];row.referenceEvidence=row.references.slice(0,25).map(r=>r.path);row.releasableBytes=0;row.recovery='本轮未删除；恢复无需操作。未来若批准删除，须先保留原 key、内容、元数据与校验摘要的可恢复副本。';}
const currentRegistry=JSON.parse(fs.readFileSync('content/registry/public-assets.json'));
const currentCodes=new Map(currentRegistry.assets.map(a=>[a.asset_code,a.object_key]));
const conflicts=[];
for(const row of review.rows)for(const reg of row.registrations){const target=currentCodes.get(reg.assetCode);if(target&&target!==row.key&&(row.runtimeObserved.length||row.references.some(r=>r.runtime&&r.kind==='EXACT_KEY'))){
 if(target.endsWith('/')&&row.key.startsWith(target))continue; // Directory prefix + concrete page naming are compatible.
 if(row.key.startsWith('images/hero/books/')&&target.startsWith('books/covers/'))continue; // Book records carry distinct hero and cover roles.
 const conflict={key:row.key,assetCode:reg.assetCode,currentRegistryKey:target,registration:reg.path,reason:'当前同代码登记指向另一 key，而旧 key 仍有直接消费者或线上请求；可能是必要变体/历史消费者，待逐消费者确认'};conflicts.push(conflict);row.classification='错绑或仍调用旧版本';row.reason=conflict.reason;
}}
